{"text": "# ═══════════════════════════════════════════════════════════════════════════
# 설비 등록부 — 정본 (HANDOFF §2-2 확장, §2-1 ④ 작업 정의)
#
# 이 파일 하나가 설비·신호·명령·작업 정의의 정본이다. shared/registry/generate.py 가
# 여기서 엣지 설정, UNS 토픽, Kafka 키, Flink 규칙 범위, JSON Schema,
# 작업 정의 표 두 개(OT 수신기용 / DMZ·IT 허용 목록), PostgreSQL 등록부 SQL 을 만든다.
# 속성 이름은 ISA-95(사이트·구역·라인·설비)와 AAS(식별자·의미 ID) 이름을 따른다.
# 가상설비 물리 파라미터·고장 정의는 0_plant/simulator/plant.yaml 에 남는다(현장 장치 쪽 정본).
# ═══════════════════════════════════════════════════════════════════════════

hierarchy:            # ISA-95 설비 계층. 토픽 = {site}/{area}/{line}/{asset}/{kind}/{name}
  site: AR-100
  area: reaction
  line: reactor-line-01

# ── 신호 종류별 수집 값(17번 D2 추천, HANDOFF §2-2 표) ──────────────────────
#   scan_s·max_interval_s 는 공정(설비) 시간. 벽시계 = 공정 ÷ 배속, 하한은 엣지 폴링 주기.
#   deadband_rule: noise_half = 가상 센서 잡음(0_plant/simulator/plant.yaml noise)의 ½ (계기 정밀도의 ½ 역할)
#   표에 없는 신호(액위·pH·전도도)는 같은 규칙으로 deadband 를 정하고 scan_s 는 가까운 종류를 따른다(설계 기본값).
signal_classes:
  temperature: { scan_s: 10, deadband_rule: noise_half, max_interval_s: 600 }
  pressure:    { scan_s: 5,  deadband_rule: noise_half, max_interval_s: 600 }
  flow:        { scan_s: 5,  deadband_rule: noise_half, max_interval_s: 600 }
  level:       { scan_s: 5,  deadband_rule: noise_half, max_interval_s: 600 }
  vibration:   { scan_s: 10, deadband_rule: noise_half, max_interval_s: 600 }
  current:     { scan_s: 10, deadband_rule: noise_half, max_interval_s: 600 }
  analytic:    { scan_s: 10, deadband_rule: noise_half, max_interval_s: 600 }
  state:       { scan_s: 1,  deadband: 0,               max_interval_s: 28800 }

# ── 설비 종류 모델(UDT 흉내). 인스턴스는 아래 assets ─────────────────────────
equipment_types:
  Tank:        { description: "저장 탱크" }
  Reactor:     { description: "교반 반응기" }
  Pump:        { description: "원심 펌프(가변속)" }
  ControlValve: { description: "제어 밸브" }
  Agitator:    { description: "교반기(전동기)" }
  Heater:      { description: "재킷 히터" }
  Cooler:      { description: "냉각기(재킷 냉각 코일)" }
  Strainer:    { description: "이중 스트레이너(A/B 바스켓)" }
  Controller:  { description: "제어기(soft-PLC)" }

# ── 설비 개체 ───────────────────────────────────────────────────────────────
#   signals[].plc_ir : PLC 입력 레지스터(float32 시작 주소, OpenPLC %IW) — 엣지가 FC4 로 읽는다
#   commands[].code  : PLC 명령 코드(PLC 프로그램 1_control/plc-openplc/project/pous/programs/main.st 와 같은 값)
#   commands[].control_point: AI 온톨로지의 제어점(ControlPoint) 이름
assets:
  - id: TK-101
    type: Tank
    name: "원료탱크"
    signals:
      - { tag: LT-101, class: level, unit: "%", desc: "원료탱크 레벨", lsl: 10.0, usl: 95.0, plc_ir: 0 }
  - id: R-101
    type: Reactor
    name: "반응기"
    signals:
      - { tag: LT-102, class: level,       unit: "%",     desc: "반응기 레벨", lsl: 15.0, usl: 90.0, plc_ir: 2 }
      - { tag: TT-101, class: temperature, unit: "degC",  desc: "반응기 온도", lsl: 40.0, usl: 95.0, plc_ir: 4 }
      - { tag: PT-101, class: pressure,    unit: "barg",  desc: "반응기 압력", lsl: null, usl: 6.0,  plc_ir: 8 }
      - { tag: pH-101, class: analytic,    unit: "pH",    desc: "반응기 pH",   lsl: 6.2,  usl: 8.4,  plc_ir: 20 }
      - { tag: CT-101, class: analytic,    unit: "mS/cm", desc: "전도도",      lsl: null, usl: null, plc_ir: 22 }
      - { tag: PT-102, class: pressure,    unit: "barg",  desc: "반응기 압력(독립 계기)", lsl: null, usl: 6.0, plc_ir: 36 }
    commands:
      - { name: temp_sp, control_point: temp_sp_x10, code: 7, kind: setpoint, unit: "degC", scale: 10, min: 20.0, max: 100.0, desc: "반응기 온도 설정값" }
  - id: HX-101
    type: Heater
    name: "재킷 히터"
    signals:
      - { tag: TT-102, class: temperature, unit: "degC", desc: "재킷 온도", lsl: null, usl: 125.0, plc_ir: 6 }
    commands:
      - { name: enable, control_point: heater_enable, code: 3, kind: switch, desc: "재킷 히터 Enable" }
  - id: HX-102
    type: Cooler
    name: "냉각기"
    signals:
      - { tag: FT-103, class: flow,        unit: "m3/h", desc: "냉각수 유량",      lsl: 20.0, usl: null, plc_ir: 28 }
      - { tag: TT-103, class: temperature, unit: "degC", desc: "냉각수 공급 온도", lsl: null, usl: 28.0, plc_ir: 30 }
      - { tag: TT-104, class: temperature, unit: "degC", desc: "냉각수 회수 온도", lsl: null, usl: 45.0, plc_ir: 32 }
    commands:
      - { name: enable, control_point: cooler_enable, code: 4, kind: switch, desc: "가상 냉각기 Enable" }
  - id: ST-103
    type: Strainer
    name: "냉각수 스트레이너"
    signals:
      - { tag: PDT-103, class: pressure, unit: "bar", desc: "스트레이너 차압", lsl: null, usl: 0.8, plc_ir: 34 }
  - id: P-101
    type: Pump
    name: "공급 펌프"
    signals:
      - { tag: FT-101, class: flow,    unit: "m3/h", desc: "공급 유량", lsl: null, usl: null, plc_ir: 10 }
      - { tag: IT-101, class: current, unit: "A",    desc: "펌프 전류", lsl: null, usl: 14.0, plc_ir: 14 }
    commands:
      - { name: run,      control_point: pump_run,      code: 1, kind: switch,   desc: "공급 펌프 기동" }
      - { name: speed_sp, control_point: pump_speed_sp, code: 5, kind: setpoint, unit: "%", scale: 1, min: 0, max: 100, desc: "펌프 속도 설정값" }
  - id: CV-101
    type: ControlValve
    name: "배출 밸브"
    signals:
      - { tag: FT-102, class: flow, unit: "m3/h", desc: "배출 유량", lsl: null, usl: null, plc_ir: 12 }
    commands:
      - { name: open_sp, control_point: valve_open_sp, code: 6, kind: setpoint, unit: "%", scale: 1, min: 0, max: 100, desc: "밸브 개도 설정값" }
  - id: M-101
    type: Agitator
    name: "교반기"
    signals:
      - { tag: IT-102, class: current,   unit: "A",    desc: "교반기 전류", lsl: null, usl: 9.6, plc_ir: 16 }
      - { tag: VT-101, class: vibration, unit: "mm/s", desc: "교반기 진동", lsl: null, usl: 7.1, plc_ir: 18 }
    commands:
      - { name: run, control_point: agitator_run, code: 2, kind: switch, desc: "교반기 기동" }
  - id: PLC-01
    type: Controller
    name: "제어기"
    signals: []
    commands:
      - { name: mode,        code: 10, kind: mode, desc: "운전 모드(1=REMOTE_MANUAL, 2=REMOTE_AUTO)" }
      - { name: maintenance, code: 11, kind: maintenance_on, desc: "정비 모드 켜기(값 = 담당자 ID)" }
      - { name: interlock_reset, code: 12, kind: reset, desc: "고압 인터록 리셋(압력이 해제 값 아래일 때만, 운전원만)" }

# ── 제어기(soft-PLC) 설정 — shared/registry/generate.py 가 PLC 프로그램 상수로 넣는다 ──
controller:
  interlock:                 # 고압 인터록: trip_barg 에서 트립·펌프 정지(기억), reset_barg 아래에서 운전원 리셋으로 해제
    tag: PT-101
    trip_barg: 6.5
    reset_barg: 5.2
  feedback_timeout_s: 5      # 되읽기 감시: 기동 명령 뒤 전류가 안 오르면 정지(벽시계 초)
  running_current_a: 1.0     # 전동기 운전 판정 전류(펌프·교반기)
  dry_run_min_level_pct: 5.0 # 펌프 기동 물리 타당성: 원료탱크 레벨이 이보다 낮으면 거부
  field_comm_timeout_s: 3    # 현장 장치 스캔 순번이 이 시간 동안 안 바뀌면 통신 이상(벽시계 초)
  time_sync_timeout_s: 5     # 엣지 시각 동기가 이 시간 넘게 멈추면 만료 검사를 할 수 없어 외부 요청 거부

# ── 작업 정의(OPC UA ISA-95 Job Control 의 WorkMaster). 외부 시스템(우리 AI)이 요청할 수 있는 것만 ──
#   parameters 가 없으면 고정 값 명령. 있으면 요청의 job_order_parameters 로 값과 범위를 받는다.
#   field_task 가 있으면 PLC 명령이 아니라 현장 정비 작업이다: OT 수신기가 가상 정비팀에게 넘긴다.
#   requires_maintenance: PLC 정비 모드(원격 명령 차단)가 켜져 있어야 받는다. 정비 해제는 따로 WM-FLD-LOTO-RELEASE(작업 완료 확인 뒤 정비팀이 해제 키).
work_masters:
  - id: WM-M101-STOP
    equipment_id: M-101
    command: run
    value: 0
    desc: "교반기 정지(AI stop_mixer)"
  - id: WM-HX102-ENABLE
    equipment_id: HX-102
    command: enable
    value: 1
    desc: "냉각기 기동(AI enable_cooling)"
  - id: WM-R101-TEMPSP
    equipment_id: R-101
    command: temp_sp
    parameters:
      - { id: temp_sp_c, min: 60.0, max: 80.0, unit: "degC" }
    desc: "반응기 온도 설정값 변경(운전 범위 안 조정)"
  - id: WM-M101-START
    equipment_id: M-101
    command: run
    value: 1
    desc: "교반기 재기동(정비 뒤)"
  - id: WM-P101-SPEED
    equipment_id: P-101
    command: speed_sp
    parameters:
      - { id: pump_speed_pct, min: 20.0, max: 80.0, unit: "%" }
    desc: "공급 펌프 속도 변경(부하 조정)"
  - id: WM-P101-STOP
    equipment_id: P-101
    command: run
    value: 0
    desc: "공급 펌프 정지"
  - id: WM-P101-START
    equipment_id: P-101
    command: run
    value: 1
    desc: "공급 펌프 재기동"
  - id: WM-PLC-MAINT-ON
    equipment_id: PLC-01
    command: maintenance
    value: 901
    desc: "정비 모드 켜기(원격 명령 차단·정비팀 901 작업 시작)"
  # ── 현장 정비(가상 정비팀) ──
  - { id: WM-FLD-STRAINER-SWITCH, equipment_id: ST-103, field_task: strainer_switch, desc: "냉각수 스트레이너 예비 바스켓 전환" }
  - { id: WM-FLD-STRAINER-CLEAN,  equipment_id: ST-103, field_task: strainer_clean,  desc: "대기 바스켓 분해 세척" }
  - { id: WM-FLD-JACKET-DESCALE,  equipment_id: HX-102, field_task: jacket_descale,  requires_maintenance: true, desc: "재킷 냉각 코일 화학 세정" }
  - { id: WM-FLD-BEARING-REPLACE, equipment_id: M-101,  field_task: bearing_replace, requires_maintenance: true, desc: "교반기 베어링 점검·교체" }
  - { id: WM-FLD-SHAFT-ALIGN,     equipment_id: M-101,  field_task: shaft_align,     requires_maintenance: true, desc: "교반기 축 정렬 점검·조정" }
  - { id: WM-FLD-PT101-CALIBRATE, equipment_id: R-101,  field_task: pt_calibrate,    desc: "PT-101 비교 교정(계기 격리)" }
  - { id: WM-FLD-CV101-REPAIR,    equipment_id: CV-101, field_task: cv_repair,       requires_maintenance: true, desc: "배출 밸브 분해 정비" }
  - { id: WM-FLD-LOTO-RELEASE,    equipment_id: PLC-01, field_task: release_lockout, requires_maintenance: true, release_maintenance: true, desc: "작업 완료 확인·격리 해제·정비 해제 키" }

# ── 요청자·승인자 허용 목록(DMZ 게이트웨이 경계 검사) ──
requesters:                    # 요청을 만드는 외부 시스템 ID 와 종류(요청 필드 requester·requester_type 이 둘 다 맞아야 한다)
  - { id: ai-ops, type: ai }     # AI 업무 도우미
  - { id: mes-01, type: mes }    # MES 흉내(생산 지시를 같은 요청 길로 보낸다)
approvers: [operator-01, operator-02, planner-01]   # planner-01: MES 생산 계획 담당
", "sha256": "ea6785aadeb1de6bd425a1fcdf45859f606d7316c0c8991f6802fc4d86c79e49", "filename": "equipment.yaml"}

